mapper.select:
select t.monitor_photo,t.monitor_photo monitorPhoto,t.monitor_type,t.monitor_type
monitorType,t.machine_id,t.machine_id machineId,t.machine_code,t.machine_code machineCode,t.model_id,t.model_id
modelId,t.remark,t.community_id,t.community_id communityId,t.mp_id,t.mp_id mpId,mm.model_name modelName,
mma.machine_name machineName,td.name monitorTypeName
from monitor_pool t
left join monitor_model mm on t.model_id = mm.model_id
left join monitor_machine mma on t.machine_id = mma.machine_id
left join t_dict td on t.monitor_type = td.status_cd and td.table_name = 'monitor_pool' and td.table_columns = 'monitor_type'
where 1 =1 and mm.status_cd = '0' and mma.status_cd = '0'

    and t.monitor_photo= #{monitorPhoto}


    and t.monitor_type= #{monitorType}


    and t.machine_id= #{machineId}


    and t.machine_code= #{machineCode}


    and t.model_id= #{modelId}


    and t.remark= #{remark}


    and t.community_id= #{communityId}


    and t.mp_id= #{mpId}


    and t.status_cd= #{statusCd}

order by t.create_time desc

    limit #{page}, #{row}

